<?php
declare(strict_types=1);
require dirname(__DIR__).'/vendor/autoload.php';
$path=$argv[1]??dirname(__DIR__).'/database/feed.example.json';if(!is_file($path)){fwrite(STDERR,"Feed not found: {$path}\n");exit(1);}try{$feed=json_decode(file_get_contents($path),true,512,JSON_THROW_ON_ERROR);$db=(new HomeScope\Database())->connection();$db->beginTransaction();$stmt=$db->prepare('UPDATE listings SET price=:price,psf=:psf,status=:status,updated_at=NOW() WHERE external_id=:external_id');$updated=0;foreach($feed as $row){if(!isset($row['external_id'],$row['price'],$row['psf']))throw new InvalidArgumentException('Every feed row requires external_id, price and psf.');$stmt->execute(['external_id'=>$row['external_id'],'price'=>(int)$row['price'],'psf'=>(int)$row['psf'],'status'=>$row['status']??'published']);$updated+=$stmt->rowCount();}$db->commit();(new HomeScope\Cache())->flushListings();echo json_encode(['status'=>'ok','updated'=>$updated,'processed'=>count($feed)])."\n";}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();fwrite(STDERR,json_encode(['status'=>'failed','message'=>$e->getMessage()])."\n");exit(1);}
